// SPDX-License-Identifier: MIT
pragma solidity ^0.8.24;

import {Test} from "forge-std/Test.sol";
import {FeeSplitter} from "../../contracts/FeeSplitter.sol";

contract SplitRemainderTest is Test {
    function test_remainderStays() public {
        address[] memory payees = new address[](3);
        payees[0] = address(1);
        payees[1] = address(2);
        payees[2] = address(3);
        FeeSplitter splitter = new FeeSplitter(payees);
        vm.deal(address(this), 10);
        splitter.split{value: 10}();
        assertEq(address(splitter).balance, 1);
    }
}
